{"implementation":"def solve(case):
    segments = case["segments"]
    allocations = [segment["minimum"] for segment in segments]
    total = sum(allocations)
    budget = case["budget"]

    if budget > total:
        remaining = min(budget, sum(segment["capacity"] for segment in segments)) - total
        while remaining > 0:
            active = [i for i, segment in enumerate(segments) if allocations[i] < segment["capacity"]]
            if not active:
                break
            weight_total = sum(segments[i]["importance"] for i in active)
            if weight_total <= 0:
                order = active
                additions = {i: 0 for i in active}
            else:
                additions = {}
                remainders = []
                used = 0
                for i in active:
                    room = segments[i]["capacity"] - allocations[i]
                    numerator = remaining * segments[i]["importance"]
                    amount = min(room, numerator // weight_total)
                    additions[i] = amount
                    used += amount
                    remainders.append((numerator % weight_total, -i, i))
                order = [item[2] for item in sorted(remainders, reverse=True)]
            for i in active:
                allocations[i] += additions[i]
            remaining -= sum(additions.values())
            for i in order:
                if remaining == 0:
                    break
                if allocations[i] < segments[i]["capacity"]:
                    allocations[i] += 1
                    remaining -= 1
            if not order:
                break

    by_name = {segment["name"]: allocations[i] for i, segment in enumerate(segments)}
    return {"allocations": allocations, "by_name": by_name, "total": sum(allocations)}"}
